hits = repo.search("compatibility|smoke|legacy frame")
r3 = env.run(["ls", "-la"], check = False)
result({
  "hits": [("%s:%d: %s" % (h.path, h.line, h.text.strip())) for h in hits],
  "ls_code": r3.code, "ls": r3.stdout[:2000], "ls_err": r3.stderr[:500],
})

all_files = env.run(["find", "data"], check=False).stdout
hidden = env.run(["ls", "-la", "data"], check=False).stdout
wc = env.run(["wc", "-l", "-c", "data/a.txt", "data/b.txt"], check=False).stdout

def count_lines(s):
    n = s.count("\n")
    if n == 0:
        return 0 if s == "" else 1
    if not s.endswith("\n"):
        n = n + 1
    return n

def count_blank(s):
    c = 0
    for l in s.split("\n")[:-1]:
        if l.strip() == "":
            c = c + 1
    return c

a = repo.read("data/a.txt")
b = repo.read("data/b.txt")
counts = {"data/a.txt": count_lines(a), "data/b.txt": count_lines(b)}
blanks = {"data/a.txt": count_blank(a), "data/b.txt": count_blank(b)}
total = 0
for k in counts:
    total = total + counts[k]
return {
  "find_all": all_files,
  "ls_la": hidden,
  "wc": wc,
  "counts": counts,
  "blanks": blanks,
  "total": total,
  "status": repo.status(),
}

